-- 311: Original BrillaPrep WASSCE BrillaPrep transitional Typewriting beta content blueprint questions, part 3.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_311_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_311_guard;
INSERT INTO _migration_311_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_typewriting_b005_011' AND NOT (q.topic_id IS 'topic_was_typewriting_b005_3' AND q.subject_id IS 'subj_wassce_typewriting' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Where is the subject heading placed in a business letter?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. To identify the correspondence or file for retrieval and reply","B. It alerts the recipient to accompanying documents and helps detect omissions","C. In a clear position before the body according to the selected letter style","D. A complete deliverable name and postal address arranged clearly"]' AND q.correct_answer IS 'C' AND q.explanation IS 'The stated answer applies the governing subject principle directly and distinguishes it from the other same-topic alternatives. Therefore the correct answer is C: In a clear position before the body according to the selected letter style.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_typewriting_b005_3' AND q.command_word IS 'Apply' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_typewriting_b005_011' AND NOT (r.batch_id IS 'wassce-foundation-beta-005' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Typewriting practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2023/03/Business20.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
